input.content:
workspace "Hospital Appointment System" {

    model {
        patient = person "Patient" {
            description "A patient who books and manages hospital appointments."
        }

        appointmentSystem = softwareSystem "Appointment System" {
            description "Manages hospital appointments for patients and doctors."

            bookingWebApp = container "Booking Web App" "Allows patients to view availability and book appointments" "Web"
            schedulingService = container "Scheduling Service" "Assigns appointments to doctors and rooms" "Service"

            patient -> bookingWebApp "Books appointments" "HTTPS"
            bookingWebApp -> schedulingService "Requests appointment scheduling" "gRPC"
        }
    }

    views {
        systemContext appointmentSystem "SystemContext" {
            include *
            autoLayout
        }
    }
}

